<?php use App\Core\Db; if($_SERVER['REQUEST_METHOD']!=='POST') exit; csrf_validate(); $pdo=Db::pdo(); $u=\App\Core\Auth::user(); $vp=$pdo->query("SELECT id,name,email FROM employees WHERE is_active=1 AND position='부사장' LIMIT 1")->fetch(); $ceo=$pdo->query("SELECT id,name,email FROM employees WHERE is_active=1 AND position IN ('대표','대표이사') LIMIT 1")->fetch(); if(!$vp||!$ceo){flash_set('danger','부사장/대표 등록 필요'); header('Location: ?r=approval_create'); exit;} $pdo->beginTransaction(); $pdo->prepare("INSERT INTO cpms_approval_documents (doc_type,title,content,doc_status,current_step_order,created_by_id,created_by_name,created_at,updated_at) VALUES (:t,:ti,:c,'PENDING',1,:uid,:un,NOW(),NOW())")->execute(array(':t'=>$_POST['doc_type'],':ti'=>$_POST['title'],':c'=>$_POST['content'],':uid'=>$u['id'],':un'=>$u['name'])); $did=(int)$pdo->lastInsertId(); $ids=array((int)$_POST['gongmu_id'],(int)$_POST['manage_id'],(int)$vp['id'],(int)$ceo['id']);$roles=array('공무','관리','부사장','대표'); for($i=0;$i<4;$i++){ $e=$pdo->query("SELECT id,name,email FROM employees WHERE id=".$ids[$i])->fetch(); $ls=($i===0)?'PENDING':'WAITING'; $pdo->prepare("INSERT INTO cpms_approval_lines (document_id,line_order,role_type,approver_id,approver_name,approver_email,line_status) VALUES (?,?,?,?,?,?,?)")->execute(array($did,$i+1,$roles[$i],$e['id'],$e['name'],$e['email'],$ls)); } $pdo->commit(); header('Location: ?r=approval_detail&id='.$did);